/**
 * Check if a string is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (typeof text !== 'string') return false;
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (!match) return false;

  const [, yearStr, monthStr, dayStr] = match;
  const year = parseInt(yearStr, 10);
  const month = parseInt(monthStr, 10);
  const day = parseInt(dayStr, 10);

  // Create date in UTC and verify it matches the input
  const date = new Date(Date.UTC(year, month - 1, day));
  if (isNaN(date.getTime())) return false;

  // Verify the parsed components match the input (catches invalid dates like 2025-02-30)
  return (
    date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day
  );
}

/**
 * Add days to a date string (in UTC).
 * @param {string} dateStr - Date in YYYY-MM-DD format
 * @param {number} days - Number of days to add (can be negative)
 * @returns {string} New date in YYYY-MM-DD format
 */
export function addDays(dateStr, days) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!match) throw new Error(`Invalid date format: ${dateStr}`);

  const [, yearStr, monthStr, dayStr] = match;
  const year = parseInt(yearStr, 10);
  const month = parseInt(monthStr, 10);
  const day = parseInt(dayStr, 10);

  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCDate(date.getUTCDate() + days);

  const newYear = date.getUTCFullYear();
  const newMonth = String(date.getUTCMonth() + 1).padStart(2, '0');
  const newDay = String(date.getUTCDate()).padStart(2, '0');

  return `${newYear}-${newMonth}-${newDay}`;
}

/**
 * Calculate the number of days between two dates (b - a).
 * @param {string} dateA - First date in YYYY-MM-DD format
 * @param {string} dateB - Second date in YYYY-MM-DD format
 * @returns {number} Number of whole days (b minus a)
 */
export function daysBetween(dateA, dateB) {
  const matchA = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateA);
  const matchB = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateB);
  if (!matchA || !matchB) throw new Error(`Invalid date format`);

  const [, yearA, monthA, dayA] = matchA;
  const [, yearB, monthB, dayB] = matchB;

  const a = new Date(Date.UTC(parseInt(yearA, 10), parseInt(monthA, 10) - 1, parseInt(dayA, 10)));
  const b = new Date(Date.UTC(parseInt(yearB, 10), parseInt(monthB, 10) - 1, parseInt(dayB, 10)));

  const diffMs = b.getTime() - a.getTime();
  return Math.round(diffMs / (1000 * 60 * 60 * 24));
}

